    def __init__(self, dim):
        self.dim = dim

    def f(self, x):
        # Ensure x is within bounds
        x = np.clip(x, -5.0, 5.0)

        # Global minimum at origin
        f_value = np.sum(x**2)

        # Add multiple local minima using sinusoidal terms
